def validate_request(value: object) -> InputValidator:
    """Validate without advancing input or inserting defaults; paths use canonical schema names."""
    errors: list[str] = []
    _validate52(value, "request", errors)
    if errors:
        raise TypeError("Invalid hume TTS request:\n" + "\n".join(errors))
    _validate58(value, "request", errors)
    accepts0 = not errors
    errors.clear()
    _validate31(value, "request", errors)
    accepts1 = not errors
    errors.clear()
    _validate47(value, "request", errors)
    accepts2 = not errors
    errors.clear()
    def validate_input(item: object, field: str = "text") -> None:
        errors: list[str] = []
        if field == "text" and accepts0:
            before = len(errors)
            _validate55(item, "text item", errors)
            if len(errors) == before:
                return
        if field == "turns" and accepts1:
            before = len(errors)
            _validate56(item, "turns item", errors)
            if len(errors) == before:
                return
        if field == "turns" and accepts2:
            before = len(errors)
            _validate57(item, "turns item", errors)
            if len(errors) == before:
                return
        if not errors:
            errors.append(field + " item: streaming input is not supported by this request")
        raise TypeError("Invalid hume TTS input item:\n" + "\n".join(errors))
    return validate_input
